.mb-6{margin-bottom: 1.5rem;}
.block{display: block;}
.grid{display: grid;}
.max-w-sm{max-width: 24rem;}
.grid-cols-2{grid-template-columns: repeat(2, minmax(0px, 1fr));}
.flex-col{flex-direction: column;}
.items-start{align-items: flex-start;}
.gap-12{gap: 3rem;}
.gap-16{gap: 4rem;}
.gap-8{gap: 2rem;}
.gap-4{gap: 1rem;}
.space-y-6 > :not([hidden]) ~ :not([hidden]){--tw-space-y-reverse: 0; margin-top: calc(1.5rem * calc(1 - var(--tw-space-y-reverse))); margin-bottom: calc(1.5rem * var(--tw-space-y-reverse));}
.space-y-4 > :not([hidden]) ~ :not([hidden]){--tw-space-y-reverse: 0; margin-top: calc(1rem * calc(1 - var(--tw-space-y-reverse))); margin-bottom: calc(1rem * var(--tw-space-y-reverse));}
.border-t{border-top-width: 1px;}
.border-white\/5{border-color: rgba(255, 255, 255, 0.05);}
.bg-spirit-ink{--tw-bg-opacity: 1; background-color: rgb(11 19 22 / var(--tw-bg-opacity, 1));}
.pb-12{padding-bottom: 3rem;}
.pt-24{padding-top: 6rem;}
.pt-8{padding-top: 2rem;}
.font-montserrat{font-family: Montserrat, sans-serif;}
.text-\[10px\]{font-size: 10px;}
.font-light{font-weight: 300;}
.font-bold{font-weight: 700;}
.leading-relaxed{line-height: 1.625;}
.tracking-widest{letter-spacing: 0.1em;}
.text-spirit-sun{--tw-text-opacity: 1; color: rgb(251 191 36 / var(--tw-text-opacity, 1));}
.text-white\/40{color: rgba(255, 255, 255, 0.4);}
.text-white\/20{color: rgba(255, 255, 255, 0.2);}
.hover\:text-white:hover{--tw-text-opacity: 1; color: rgb(255 255 255 / var(--tw-text-opacity, 1));}
@media (min-width: 640px){.sm\:flex-row{flex-direction: row;}}
@media (min-width: 768px){.md\:col-span-1{grid-column: span 1 / span 1;}}
@media (min-width: 768px){.md\:grid-cols-3{grid-template-columns: repeat(3, minmax(0px, 1fr));}}
@media (min-width: 1024px){.lg\:col-span-5{grid-column: span 5 / span 5;}}
@media (min-width: 1024px){.lg\:col-span-7{grid-column: span 7 / span 7;}}
@media (min-width: 1024px){.lg\:grid-cols-12{grid-template-columns: repeat(12, minmax(0px, 1fr));}}
